CREATE TABLE quartos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero VARCHAR(255) NOT NULL UNIQUE, tipo VARCHAR(255) NOT NULL, capacidade INTEGER NOT NULL CHECK(capacidade BETWEEN 1 AND 10), diaria NUMERIC(12,2) NOT NULL CHECK(diaria > 0), ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE hospedes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255) NOT NULL, documento VARCHAR(255) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL, telefone VARCHAR(255) NOT NULL);
CREATE TABLE reservas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, quarto_id BIGINT NOT NULL REFERENCES quartos(id), hospede_id BIGINT NOT NULL REFERENCES hospedes(id), entrada DATE NOT NULL, saida DATE NOT NULL, diaria NUMERIC(12,2) NOT NULL CHECK(diaria>0), valor_total NUMERIC(12,2) NOT NULL CHECK(valor_total>0), status VARCHAR(255) NOT NULL CHECK(status IN ('CONFIRMADA','HOSPEDADO','FINALIZADA','CANCELADA')), CHECK(saida > entrada));
CREATE INDEX idx_reserva_periodo ON reservas(quarto_id,entrada,saida);
CREATE INDEX idx_reserva_hospede ON reservas(hospede_id);
